export const UpdateInvoiceGroupOutcomeParams = zod.object({
  id: zod.coerce.number(),
});

export const updateInvoiceGroupOutcomeBodyOverrideReasonMin = 20;

export const UpdateInvoiceGroupOutcomeBody = zod
  .object({
    outcome: zod.string(),
    closureReason: zod
      .enum(["denied_by_payor", "cannot_dispute", "non_issue"])
      .optional()
      .describe(
        "Canonical set of structured-closure reasons. Defined once here so\nevery request schema that accepts a closure decision\n(UpdateClaimOutcomeBody, UpdateInvoiceGroupOutcomeBody,\nCreateClosureRequest) generates the exact same TypeScript union —\na typo or drift between sites becomes a typecheck error instead\nof a silent coercion through `as` casts at the call site.\n",
      ),
    approvedAmount: zod.string().optional(),
    closureCategory: zod.string().nullish(),
    closureCategoryOther: zod.string().nullish(),
    closureRootCause: zod.string().nullish(),
    closureRootCauseOther: zod.string().nullish(),
    closureNarrative: zod.string().nullish(),
    closureAccountabilityTags: zod
      .array(
        zod
          .enum([
            "driver",
            "dispatcher",
            "member",
            "it_system",
            "our_staff",
            "external_payor",
            "other",
          ])
          .describe(
            "Canonical set of accountability tags recorded on a structured\nclosure. Defined once here so every request and response schema\nsees the exact same generated TypeScript union — adding a tag in\none place without updating the others becomes a typecheck error\ninstead of a silent runtime drift.\n",
          ),
      )
      .nullish(),
    closureAccountabilityOther: zod.string().nullish(),
    closureDrivers: zod
      .array(
        zod
          .object({
            name: zod.string(),
            id: zod.string().nullish(),
          })
          .describe(
            "A person referenced from a structured closure (driver\/dispatcher).",
          ),
      )
      .nullish(),
    closureDispatchers: zod
      .array(
        zod
          .object({
            name: zod.string(),
            id: zod.string().nullish(),
          })
          .describe(
            "A person referenced from a structured closure (driver\/dispatcher).",
          ),
      )
      .nullish(),
    closureCommunicatedTo: zod.string().nullish(),
    closureAddressedAt: zod.coerce.date().nullish(),
    closureAddressedBy: zod.string().nullish(),
    closureAddressedByEmail: zod.string().nullish(),
    closureReviewNotes: zod.string().nullish(),
    closureResponsibility: zod
      .union([
        zod
          .enum([
            "agent_mistake",
            "driver_mistake",
            "system_error",
            "external_payor",
            "no_one_process_limit",
          ])
          .describe(
            'Task #888 — five-value canonical responsibility recorded by the\nslim closure intake modal. Mirrors `@workspace\/closure-responsibility`.\nEach value maps to exactly one supervisor \"responsible role\":\nagent_mistake → Contact Center Manager,\ndriver_mistake → Contractor Relations Coordinator,\nsystem_error \/ external_payor \/ no_one_process_limit → IT Coordinator \/ COO.\n',
          ),
        zod.null(),
      ])
      .optional()
      .describe(
        "Task #888 — same contract as `UpdateClaimOutcomeBody.closureResponsibility`.",
      ),
    override: zod
      .object({
        reason: zod
          .string()
          .min(updateInvoiceGroupOutcomeBodyOverrideReasonMin),
      })
      .nullish()
      .describe(
        "Task #758 — terminal-closure override. Supply when the operator\nis closing a leg or group into a terminal outcome (Denied,\nApproved, Partially Approved, Non-Issue, Withdrawn, No Action\nNeeded) from a source status whose normal outcome envelope does\nnot permit it (e.g. Ready to Review, Portal Queued, Generating\nEmail, On Hold, Awaiting Response → Non-Issue). The reason is\nrequired (≥20 chars), recorded in the audit-log metadata as\n`override:{applied,sourceStatus,targetOutcome,reason}` and\nappended to the lifecycle note. Omitted on the normal lane.\n",
      ),
  })
  .describe(
    "Body for `PATCH \/invoice-groups\/{id}\/outcome`. Same closure detail\ncontract as `UpdateClaimOutcomeBody`.\n",
  );

