/**
 * @summary Get valid status and outcome transitions for a claim
 */
export const GetClaimValidTransitionsParams = zod.object({
  id: zod.coerce.number(),
});

export const GetClaimValidTransitionsResponse = zod.object({
  currentStatus: zod.string().optional(),
  currentOutcome: zod.string().optional(),
  validStatuses: zod.array(zod.string()).optional(),
  validOutcomes: zod.array(zod.string()).optional(),
  terminalLane: zod
    .record(zod.string(), zod.enum(["normal", "override"]))
    .optional()
    .describe(
      'Task #758 — per-target terminal-outcome lane map. For each\nterminal outcome (Denied, Approved, Partially Approved,\nNon-Issue, Withdrawn, No Action Needed), tells the closure\ndialogs whether the writer accepts that target on the\nnormal lane (`\"normal\"`) or requires `override.reason`\n≥20 chars (`\"override\"`).\n',
    ),
  hasActiveSubmission: zod.boolean().optional(),
  canQueueForPortal: zod.boolean().optional(),
  hasBeenSubmitted: zod
    .boolean()
    .optional()
    .describe(
      "True if at least one portal_submission has ever existed for this claim (active or terminal).",
    ),
  postResponseActions: zod.array(zod.string()).optional(),
  latestResponseType: zod.string().nullish(),
  hasResponse: zod
    .boolean()
    .optional()
    .describe("True if a portal\/email response exists for this claim."),
  awaitingPayorAgainAt: zod.coerce
    .date()
    .nullish()
    .describe(
      "Echo of `invoice_groups.awaiting_payor_again_at` for the claim's group. Surfaced so the Responses Awaiting Review UI can decide whether the 'I replied — wait for payor again' button should be enabled. Always present on group endpoints; on claim endpoints it falls back to the parent group's value when joinable.",
    ),
});

